{
  "title": "tBreg Impact on Tumor Growth",
  "perWatchSecond": 1,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "tBregs Drive Maximum Tumor Size",
      "goal": "Show that a high tBreg population forces the tumor to reach its carrying capacity despite strong NK activity.",
      "control": {
        "parameter": "m_T",
        "label": "Tumor‑induced tBreg growth rate",
        "lowEnd": "0 (no tBreg activation)",
        "highEnd": "1e-14 (double the paper's value)"
      },
      "watch": "t (tumor cells)",
      "whatIf": {
        "prompt": "What if tumor‑induced tBreg growth is doubled?",
        "parameter": "m_T",
        "value": 1e-14
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "higher",
        "by": 30
      },
      "effect": "With doubled m_T, the tumor peak rises from about 99 to over 129, showing tBregs can push the tumor to its maximum size.",
      "prediction": {
        "prompt": "Predict the tumor peak with doubled m_T versus the original.",
        "claimed": "Higher by more than 30 units",
        "other": "Lower by more than 30 units"
      },
      "passage": {
        "title": "Headline Result",
        "quote": "a sufficiently large number of tBregs can cause the breast tumour to reach its carrying capacity, regardless of the rate of NK-induced breast cancer cell death."
      },
      "carryForward": "Keep the same NK and Treg parameters."
    },
    {
      "kind": "background",
      "finding": 1,
      "title": "NK Cells Control Tumor Without tBregs",
      "goal": "Demonstrate that without tBregs, tumor size depends on NK killing rate.",
      "control": {
        "parameter": "c",
        "label": "NK‑induced tumor death rate",
        "lowEnd": "0 (no NK killing)",
        "highEnd": "4e-10 (double the paper's value)"
      },
      "watch": "t (tumor cells)",
      "whatIf": {
        "prompt": "What if NK killing rate is doubled?",
        "parameter": "c",
        "value": 4e-10
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 40
      },
      "effect": "Doubling c reduces the tumor peak from about 99 to below 60, showing strong NK activity can suppress tumor growth when tBregs are absent.",
      "prediction": {
        "prompt": "Predict the tumor peak with doubled c versus the original.",
        "claimed": "Lower by more than 40 units",
        "other": "Higher by more than 40 units"
      },
      "passage": null,
      "carryForward": "Set initial tBregs b0 to 0 to remove them."
    },
    {
      "kind": "idea",
      "finding": 3,
      "title": "Three Stable States of the System",
      "goal": "Explore how varying NK killing rate c leads to different equilibria.",
      "control": {
        "parameter": "c",
        "label": "NK‑induced tumor death rate",
        "lowEnd": "0 (no NK killing)",
        "highEnd": "4e-10 (double the paper's value)"
      },
      "watch": "t (tumor cells)",
      "whatIf": {
        "prompt": "What if NK killing rate is set to a very low value?",
        "parameter": "c",
        "value": 1e-11
      },
      "difference": {
        "compartment": "t",
        "summary": "at",
        "at": 70,
        "time": 70,
        "relation": "higher",
        "by": 80
      },
      "effect": "With c extremely low, the tumor at day 70 reaches about 180, indicating the tumor‑present‑with‑tBregs equilibrium.",
      "prediction": {
        "prompt": "Predict tumor size at day 70 with c = 1e-11 versus the original c.",
        "claimed": "Higher by more than 80 units",
        "other": "Lower by more than 80 units"
      },
      "passage": {
        "title": "Three Equilibria",
        "quote": "We showed the existence of three biologically realistic equilibria: an equilibrium with no cancer cells, an equilibrium with cancer cells and no tBregs, and an equilibrium with both cancer cells and tBregs."
      },
      "carryForward": "Keep m_T at its doubled value from the hook level."
    },
    {
      "kind": "method",
      "finding": 4,
      "title": "Critical NK Killing Thresholds",
      "goal": "Identify the bifurcation points where tumor elimination switches to persistence.",
      "control": {
        "parameter": "c",
        "label": "NK‑induced tumor death rate",
        "lowEnd": "0.5e-10 (half the paper's value)",
        "highEnd": "3e-10 (1.5× the paper's value)"
      },
      "watch": "t (tumor cells)",
      "whatIf": {
        "prompt": "What if NK killing rate crosses the lower threshold?",
        "parameter": "c",
        "value": 0.8e-10
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 20
      },
      "effect": "Crossing the lower threshold reduces the tumor peak from ~99 to ~79, demonstrating a shift from tumor persistence to elimination.",
      "prediction": {
        "prompt": "Predict tumor peak when c is set just above the lower threshold versus the original.",
        "claimed": "Lower by more than 20 units",
        "other": "Higher by more than 20 units"
      },
      "passage": null,
      "carryForward": "Maintain the doubled m_T and zero initial tBregs."
    },
    {
      "kind": "evaluation",
      "finding": 6,
      "title": "Cancer Dormancy Emergence",
      "goal": "Show how the system can settle into a low‑level dormant tumor state.",
      "control": {
        "parameter": "a",
        "label": "Tumor growth rate",
        "lowEnd": "0.05 (much slower growth)",
        "highEnd": "0.15 (paper's value)"
      },
      "watch": "t (tumor cells)",
      "whatIf": {
        "prompt": "What if tumor growth rate is reduced to 0.05?",
        "parameter": "a",
        "value": 0.05
      },
      "difference": {
        "compartment": "t",
        "summary": "mean",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 10
      },
      "effect": "With a reduced growth rate, the average tumor size over 70 days drops from about 70 to below 60, illustrating a dormant state.",
      "prediction": {
        "prompt": "Predict the mean tumor size with a = 0.05 versus the original a.",
        "claimed": "Lower by more than 10 units",
        "other": "Higher by more than 10 units"
      },
      "passage": {
        "title": "Cancer Dormancy",
        "quote": "This phenomenon is known as cancer dormancy and it happens to 20–45% of breast cancer patients"
      },
      "carryForward": "Keep all other parameters as in the previous level."
    }
  ],
  "limits": [
    "All time units are days.",
    "Each level runs for 70 days, displayed at 4× speed (≤20 seconds).",
    "Controls adjust only rate parameters (no starting values).",
    "What‑if changes a single parameter or initial condition discussed in the paper."
  ]
}
